function validateListSessionsMessage(message: Record<string, unknown>): ValidationResult {
  const rawLimit = message.limit;
  if (rawLimit !== undefined && !isWholeNumber(rawLimit)) {
    return {valid: false, error: 'list_sessions limit must be a non-negative integer'};
  }

  const cursor = message.before === undefined ? undefined : parseCursor(message.before);
  if (message.before !== undefined && cursor === undefined) {
    return {valid: false, error: 'list_sessions before must have a valid sessionId and updatedAt'};
  }

  const frame: ListSessionsMessage = {type: 'list_sessions'};
  if (isWholeNumber(rawLimit)) frame.limit = rawLimit;
  if (cursor !== undefined) frame.before = cursor;
  return {valid: true, data: frame};
}

function isWholeNumber(value: unknown): value is number {
  return typeof value === 'number' && Number.isInteger(value) && value >= 0;
}

