/** Terminates tracked clients and stops each server once its sockets have drained. */
export async function drainServers(trackedServers: HalServer[], trackedClients: WebSocket[]): Promise<void> {
  for (const client of trackedClients.splice(0)) client.terminate();
  for (const hal of trackedServers.splice(0)) {
    const {wss} = hal;
    await eventually(() => wss.clients.size === 0);
    await hal.stop();
  }
}

/** Polls until `check()` succeeds or 500ms elapse, for socket close assertions. */
export async function eventually(check: () => boolean): Promise<void> {
  for (let attempt = 0; attempt < 50 && !check(); attempt++) await new Promise(resolve => setTimeout(resolve, 10));
}

/** Wraps an in-memory store exposing only the five required members, so optional ones can be omitted or overridden. */
export function delegatingTo(inner: InMemorySessionStore): SessionStore {
  return {
    create: (sessionId, userId, options) => inner.create(sessionId, userId, options),
    get: sessionId => inner.get(sessionId),
    delete: sessionId => inner.delete(sessionId),
    count: () => inner.count(),
    clear: () => inner.clear(),
  };
}

